begin;create extension if not exists pgtap with schema extensions;set local role postgres;set local search_path=public,extensions;select plan(20);
select has_table('public','app_admins','admin table exists');select has_table('public','qa_entitlement_overrides','QA override table exists');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.app_admins'::regclass),'admin RLS is forced');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.qa_entitlement_overrides'::regclass),'QA RLS is forced');
select table_privs_are('public','app_admins','authenticated',array[]::text[],'users cannot enumerate or mutate admins');
select table_privs_are('public','qa_entitlement_overrides','authenticated',array[]::text[],'users cannot enumerate or mutate QA overrides');
insert into auth.users(id,email)values('91190000-0000-4000-8000-000000000001','admin@example.test'),('91190000-0000-4000-8000-000000000002','free@example.test');
delete from public.creators where owner_user_id in('91190000-0000-4000-8000-000000000001','91190000-0000-4000-8000-000000000002');
insert into public.creators(id,owner_user_id,display_name,public_slug)values('91190000-0000-4000-8000-000000000011','91190000-0000-4000-8000-000000000001','QA Admin','stage-1119-admin'),('91190000-0000-4000-8000-000000000012','91190000-0000-4000-8000-000000000002','Free User','stage-1119-free');
insert into public.app_admins(user_id,role)values('91190000-0000-4000-8000-000000000001','admin');
select throws_ok($$insert into public.app_admins(user_id,role)values('91190000-0000-4000-8000-000000000001','admin')$$,'23505',null,'admin user is unique');
select ok(public.is_app_admin('91190000-0000-4000-8000-000000000001'),'admin resolves by UUID');select isnt(public.is_app_admin('91190000-0000-4000-8000-000000000002'),true,'normal user is not admin');
insert into public.qa_entitlement_overrides(user_id,plan,environment)values('91190000-0000-4000-8000-000000000001','pro','test'),('91190000-0000-4000-8000-000000000002','pro','test');
select set_config('request.headers','{"host":"127.0.0.1:54321"}',true);select ok(public.is_local_qa_database(),'loopback database request is QA eligible');
select set_config('request.headers','{"host":"supabase_rest_project:3000","x-forwarded-host":"127.0.0.1"}',true);select ok(public.is_local_qa_database(),'local gateway forwarded host is QA eligible');
select is(public.get_provider_connection_entitlement('91190000-0000-4000-8000-000000000011','official')->>'plan','pro','admin with local override resolves Pro');
select is(public.get_provider_connection_entitlement('91190000-0000-4000-8000-000000000012','official')->>'plan','free','normal user override is ignored');
select set_config('request.headers','{"host":"project.supabase.co"}',true);select isnt(public.is_local_qa_database(),true,'hosted database request is not QA eligible');
select is(public.get_provider_connection_entitlement('91190000-0000-4000-8000-000000000011','official')->>'plan','free','admin override is ignored on hosted database');
insert into public.creator_plan_entitlements(creator_id,plan,subscription_status,source)values('91190000-0000-4000-8000-000000000011','pro','active','billing_provider');
select is(public.get_provider_connection_entitlement('91190000-0000-4000-8000-000000000011','official')->>'plan','pro','Stripe projection remains authoritative in production');
select is((select count(*)::integer from public.creator_plan_entitlements where creator_id='91190000-0000-4000-8000-000000000011'),1,'QA state does not alter billing rows');
set local role authenticated;select set_config('request.jwt.claim.sub','91190000-0000-4000-8000-000000000002',true);
select throws_ok($$insert into public.app_admins(user_id,role)values('91190000-0000-4000-8000-000000000002','admin')$$,'42501',null,'creator cannot self-admin');
select throws_ok($$delete from public.qa_entitlement_overrides where user_id='91190000-0000-4000-8000-000000000001'$$,'42501',null,'creator cannot mutate QA state');
set local role postgres;select is((select count(*)::integer from public.app_admins),1,'service role grant remains intact');select*from finish();rollback;
